return ['domain'=>'zinn-cache','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-cache','pot-creation-date'=>'2026-09-02T07:33:02+00:00','po-revision-date'=>'2026-09-02T07:33:02+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache'=>'Zinn® Cache','https://zinndigital.com/wordpress-plugins/zinn-cache'=>'https://zinndigital.com/wordpress-plugins/zinn-cache','For sites hosted with Zinn Digital®. Controls the page cache your Zinn® server already provides — smart auto-purge on content change, remote purge from your Zinn® dashboard, a Redis object-cache toggle, safe WordPress/WooCommerce exclusions, and one-click admin login. This is a cache controller, not a cache engine. Hosting elsewhere? Install Zinn® Cache Engine instead.'=>'Za stranice smještene na usluzi Zinn Digital®. Upravlja predmemorijom stranica koju vaš Zinn® poslužitelj već osigurava — pametno automatsko čišćenje pri promjeni sadržaja, udaljeno čišćenje s vaše Zinn® upravljačke ploče, prekidač za Redis objektnu predmemoriju, sigurna WordPress/WooCommerce izuzeća i administrativna prijava jednim klikom. Ovo je upravitelj predmemorije, a ne mehanizam predmemorije. Hostate negdje drugdje? Umjesto toga instalirajte Zinn® Cache Engine.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','You are not allowed to purge the cache.'=>'Nemate dopuštenje za čišćenje predmemorije.','Cache purge requested.'=>'Zatraženo je čišćenje predmemorije.','Zinn® Cache: another object-cache drop-in is installed, so the Redis object cache is not managed by this plugin.'=>'Zinn® Cache: instaliran je drugi dodatak za predmemoriju objekata, tako da Redis predmemorijom objekata ne upravlja ovaj dodatak.','Full-page cache (LiteSpeed)'=>'Predmemorija cijele stranice (LiteSpeed)','Enable LSCache control'=>'Omogući kontrolu LSCache','Send LiteSpeed cache-control and tag headers on cacheable pages.'=>'Šalji LiteSpeed cache-control i tag zaglavlja na stranicama koje se mogu predmemorirati.','Public cache lifetime (seconds)'=>'Trajanje javne predmemorije (u sekundama)','Object cache (Redis)'=>'Objektna predmemorija (Redis)','Enable Redis object cache'=>'Omogući Redis objektnu predmemoriju','Install the Redis object-cache drop-in (requires the phpredis extension).'=>'Instaliraj Redis object-cache drop-in (zahtijeva phpredis ekstenziju).','Redis host'=>'Redis poslužitelj (host)','Redis port'=>'Redis priključak (port)','Redis database'=>'Redis baza podataka','Redis key prefix'=>'Redis prefiks ključa','Automatic purging'=>'Automatsko čišćenje','Smart auto-purge'=>'Pametno automatsko čišćenje','Purge affected pages automatically when content changes.'=>'Automatski očisti pogođene stranice kada se sadržaj promijeni.','Purge on updates'=>'Čišćenje pri ažuriranjima','Purge everything after core, plugin, or theme updates.'=>'Očisti sve nakon ažuriranja jezgre, dodataka ili tema.','Cache exclusions'=>'Iznimke predmemorije','Sensible WordPress and WooCommerce defaults are always applied (cart, checkout, my-account, logged-in and session pages are never cached). Add extra rules below, one per line.'=>'Razumne zadane postavke za WordPress i WooCommerce uvijek se primjenjuju (košarica, naplata, moj račun, prijavljene stranice i stranice sa sesijom nikada se ne predmemoriraju). Dodajte dodatna pravila u nastavku, jedno po retku.','Exclude URL paths (prefix match)'=>'Isključi URL putanje (podudaranje po prefiksu)','Exclude query keys'=>'Isključi ključeve upita','Exclude cookie name prefixes'=>'Isključi prefikse naziva kolačića','Maintenance'=>'Održavanje','Purge everything now'=>'Očisti sve odmah','detected'=>'otkriveno','not detected'=>'nije otkriveno','phpredis extension missing'=>'nedostaje phpredis ekstenzija','active'=>'aktivno','inactive'=>'neaktivno','LiteSpeed cache:'=>'LiteSpeed predmemorija:','Redis object cache:'=>'Redis objektna predmemorija:','The Redis PHP extension (phpredis) is not available on this server, so the object cache cannot be enabled.'=>'Redis PHP ekstenzija (phpredis) nije dostupna na ovom poslužitelju, pa se objektna predmemorija ne može omogućiti.','Another object-cache drop-in is already installed. Remove it before enabling the Zinn® object cache.'=>'Još jedan dodatak za predmemoriju objekata (object-cache) već je instaliran. Uklonite ga prije nego što omogućite Zinn® predmemoriju objekata.','Could not write the Redis connection configuration file.'=>'Nije bilo moguće zapisati konfiguracijsku datoteku Redis veze.','The bundled object-cache drop-in could not be read.'=>'Priloženi object-cache drop-in nije bilo moguće pročitati.','Could not install the object-cache drop-in into wp-content.'=>'Nije bilo moguće instalirati object-cache drop-in u wp-content.','Could not remove the object-cache drop-in.'=>'Nije bilo moguće ukloniti object-cache drop-in.','The WordPress filesystem is not writable, so the object-cache drop-in could not be managed.'=>'WordPress datotečni sustav nije zapisiv, pa object-cache drop-in nije bilo moguće postaviti.','This one-click login link is not valid any more. Links expire after a couple of minutes and can only be used once — open your site from the Zinn® dashboard again to get a fresh one.'=>'Ova poveznica za prijavu jednim klikom više nije važeća. Poveznice istječu nakon nekoliko minuta i mogu se upotrijebiti samo jednom — otvorite svoju web-lokaciju ponovno s upravljačke ploče sustava Zinn® kako biste dobili novu.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju za Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta te nije instalirano.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje vode više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite postojeće stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude koji se time bave za život','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.']];